    # NA- Function to check if set values matches expected for stored beam

    def check_set_stored_beam(self, beam, sequence):
        try:
            beam_set = sq.waitForObject(integrity_objects.dSB_Combo_Beams)["text"]
            seq_set = sq.waitForObject(integrity_objects.dSB_Combo_Sequences)["text"]
            if seq_set == sequence and beam_set == beam:
                logger.info("SET SEQUENCE IS {}, SET BEAM IS {}".format(seq_set, beam_set))
                return True
            else:
                logger.info("INCORRECT:- SET SEQUENCE IS {}, SET BEAM IS {}".format(seq_set, beam_set))
                return False
        except Exception as e:
            logger.info("Error in check set stored beam " + str(e))
            return False

